import { apiFetch } from "./client";
import type { AutonomousCycleResponse } from "./types";

/** Autonomous cycle history entry. */
export interface AutonomousCycleHistoryEntry {
  cycle_id: string;
  domain: string;
  runs: number;
  status: "running" | "completed" | "stopped";
}

/** Autonomous cycle history response. */
export interface AutonomousHistoryResponse {
  cycles: AutonomousCycleHistoryEntry[];
}

/** Consciousness state enum matching backend ConsciousnessState. */
export type ConsciousnessState =
  | "idle"
  | "exploring"
  | "generating"
  | "evaluating"
  | "synthesizing"
  | "resting";

/** Consciousness state info from the backend. */
export interface ConsciousnessStateInfo {
  state: ConsciousnessState;
  seconds_in_state: number;
  next_action: string;
}

/** Stop a running autonomous cycle. HB-01: Requires explicit cycle_id. */
export function stopAutonomousCycle(cycleId: string): Promise<{ status: string; cycle_id: string }> {
  return apiFetch(`/pipeline/autonomous/stop?cycle_id=${encodeURIComponent(cycleId)}`, {
    method: "POST",
  });
}

/** Get autonomous cycle history. */
export function getAutonomousHistory(): Promise<AutonomousHistoryResponse> {
  return apiFetch("/pipeline/autonomous/history");
}

/** Get the current consciousness state. */
export function getConsciousnessState(): Promise<ConsciousnessStateInfo> {
  return apiFetch("/pipeline/autonomous/consciousness");
}

/** Re-export triggerAutonomous from pipeline.ts for convenience. */
export { triggerAutonomous } from "./pipeline";
export type { AutonomousCycleResponse };

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { AutonomousCycleHistoryEntry } from "@/api/autonomous";

interface CycleProgressProps {
  cycle: AutonomousCycleHistoryEntry;
  /** Optional stop handler — triggers confirmation per HB-01. */
  onStop?: (cycleId: string) => void;
}

const STATUS_COLORS: Record<string, string> = {
  running: "bg-blue-100 text-blue-800",
  completed: "bg-green-100 text-green-800",
  stopped: "bg-yellow-100 text-yellow-800",
};

export function CycleProgress({ cycle, onStop }: CycleProgressProps) {
  return (
    <Card data-testid={`cycle-progress-${cycle.cycle_id}`}>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-mono">{cycle.cycle_id}</CardTitle>
          <Badge className={STATUS_COLORS[cycle.status] || "bg-gray-100 text-gray-800"}>
            {cycle.status}
          </Badge>
        </div>
      </CardHeader>
      <CardContent>
        <div className="flex items-center justify-between text-sm">
          <span className="text-muted-foreground" data-testid={`cycle-domain-${cycle.cycle_id}`}>
            {cycle.domain}
          </span>
          <span data-testid={`cycle-runs-${cycle.cycle_id}`}>
            {cycle.runs} run{cycle.runs !== 1 ? "s" : ""}
          </span>
        </div>
        {cycle.status === "running" && onStop && (
          <button
            className="mt-2 text-xs text-destructive hover:underline"
            data-testid={`cycle-stop-${cycle.cycle_id}`}
            onClick={() => onStop(cycle.cycle_id)}
          >
            Stop Cycle
          </button>
        )}
      </CardContent>
    </Card>
  );
}

import { Badge } from "@/components/ui/badge";
import type { ConsciousnessState } from "@/api/autonomous";

interface ConsciousnessStateBadgeProps {
  state: ConsciousnessState;
  secondsInState?: number;
}

const STATE_CONFIG: Record<ConsciousnessState, { label: string; color: string }> = {
  idle: { label: "Idle", color: "bg-gray-100 text-gray-800" },
  exploring: { label: "Exploring", color: "bg-blue-100 text-blue-800" },
  generating: { label: "Generating", color: "bg-purple-100 text-purple-800" },
  evaluating: { label: "Evaluating", color: "bg-orange-100 text-orange-800" },
  synthesizing: { label: "Synthesizing", color: "bg-green-100 text-green-800" },
  resting: { label: "Resting", color: "bg-indigo-100 text-indigo-800" },
};

export function ConsciousnessStateBadge({ state, secondsInState }: ConsciousnessStateBadgeProps) {
  const config = STATE_CONFIG[state] || STATE_CONFIG.idle;

  return (
    <div className="flex items-center gap-2" data-testid="consciousness-state">
      <Badge className={config.color} data-testid="consciousness-badge">
        {config.label}
      </Badge>
      {secondsInState !== undefined && (
        <span className="text-xs text-muted-foreground" data-testid="consciousness-seconds">
          {Math.round(secondsInState)}s
        </span>
      )}
    </div>
  );
}

/**
 * Tests for BATCH-26/TASK-02: Autonomous Dashboard Components
 *
 * TEST-26-02-01: API client calls correct endpoints
 * TEST-26-02-02: CycleProgress renders cycle info
 * TEST-26-02-03: ConsciousnessState shows current state badge
 */
import { describe, it, expect, beforeEach, vi } from "vitest";
import { render, screen } from "@testing-library/react";
import { getAutonomousHistory, stopAutonomousCycle } from "@/api/autonomous";
import { apiFetch } from "@/api/client";
import { CycleProgress } from "@/components/autonomous/cycle-progress";
import { ConsciousnessStateBadge } from "@/components/autonomous/consciousness-state";
import type { AutonomousCycleHistoryEntry } from "@/api/autonomous";

// ── Mock apiFetch ───────────────────────────────────────────────

vi.mock("@/api/client", () => ({
  apiFetch: vi.fn(),
}));

const mockApiFetch = vi.mocked(apiFetch);

// ── TEST-26-02-01: API client calls correct endpoints ───────────

describe("BATCH-26/TASK-02: Autonomous API Client", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("TEST-26-02-01: API client calls correct endpoints", async () => {
    // Test getAutonomousHistory
    const mockHistory = {
      cycles: [
        {
          cycle_id: "auto_20260502_143000",
          domain: "AI/NLP",
          runs: 3,
          status: "completed",
        },
      ],
    };
    mockApiFetch.mockResolvedValueOnce(mockHistory);

    const result = await getAutonomousHistory();

    expect(mockApiFetch).toHaveBeenCalledWith("/pipeline/autonomous/history");
    expect(result.cycles).toHaveLength(1);
    expect(result.cycles[0].cycle_id).toBe("auto_20260502_143000");
    expect(result.cycles[0].status).toBe("completed");

    // Test stopAutonomousCycle
    mockApiFetch.mockResolvedValueOnce({ status: "stopped", cycle_id: "auto_test" });

    await stopAutonomousCycle("auto_test");

    expect(mockApiFetch).toHaveBeenCalledWith(
      "/pipeline/autonomous/stop?cycle_id=auto_test",
      { method: "POST" },
    );
  });
});

// ── TEST-26-02-02: CycleProgress renders cycle info ─────────────

describe("CycleProgress", () => {
  const mockCycle: AutonomousCycleHistoryEntry = {
    cycle_id: "auto_20260502_143000",
    domain: "AI/NLP",
    runs: 3,
    status: "running",
  };

  it("TEST-26-02-02: CycleProgress renders cycle info", () => {
    render(<CycleProgress cycle={mockCycle} />);

    expect(screen.getByTestId("cycle-progress-auto_20260502_143000")).toBeInTheDocument();
    expect(screen.getByText("auto_20260502_143000")).toBeInTheDocument();
    expect(screen.getByTestId("cycle-domain-auto_20260502_143000")).toHaveTextContent("AI/NLP");
    expect(screen.getByTestId("cycle-runs-auto_20260502_143000")).toHaveTextContent("3 runs");
    expect(screen.getByText("running")).toBeInTheDocument();
  });

  it("shows stop button when running and onStop provided", () => {
    const onStop = vi.fn();
    render(<CycleProgress cycle={mockCycle} onStop={onStop} />);

    expect(screen.getByTestId("cycle-stop-auto_20260502_143000")).toBeInTheDocument();
  });

  it("hides stop button when cycle is completed", () => {
    const completedCycle = { ...mockCycle, status: "completed" as const };
    const onStop = vi.fn();
    render(<CycleProgress cycle={completedCycle} onStop={onStop} />);

    expect(screen.queryByTestId("cycle-stop-auto_20260502_143000")).not.toBeInTheDocument();
  });
});

// ── TEST-26-02-03: ConsciousnessState shows current state badge ──

describe("ConsciousnessStateBadge", () => {
  it("TEST-26-02-03: ConsciousnessState shows current state badge", () => {
    render(<ConsciousnessStateBadge state="exploring" />);

    expect(screen.getByTestId("consciousness-state")).toBeInTheDocument();
    expect(screen.getByTestId("consciousness-badge")).toHaveTextContent("Exploring");
  });

  it("shows seconds when provided", () => {
    render(<ConsciousnessStateBadge state="generating" secondsInState={42.7} />);

    expect(screen.getByTestId("consciousness-badge")).toHaveTextContent("Generating");
    expect(screen.getByTestId("consciousness-seconds")).toHaveTextContent("43s");
  });

  it("renders idle state by default", () => {
    render(<ConsciousnessStateBadge state="idle" />);

    expect(screen.getByTestId("consciousness-badge")).toHaveTextContent("Idle");
  });
});

